WITH filtered_stores AS (SELECT * FROM stores WHERE region != 'East' AND store_name LIKE '%Cent%'), opened_quarter_summary AS (SELECT QUARTER(opened_date) AS opened_quarter, SUM(CASE WHEN city = 'Tokyo' THEN sqft ELSE 0 END) AS tokyo_sqft, ROUND((100 * SUM(CASE WHEN region = 'Central' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_central FROM filtered_stores GROUP BY QUARTER(opened_date)) SELECT * FROM opened_quarter_summary WHERE pct_central >= 20;
